// Timing envelope, derived from feat.config.json at generate time: a per-invoke
// allowance for the stimulus and each given: execute, plus the shared eventual
// capture window, plus margin. Changing timeouts in config regenerates this file.
const INVOKE_ALLOWANCE_MS = 30000;
const CONVERGENCE_WINDOW_MS = 0;
const TIMING_MARGIN_MS = 30000;
const HOOK_TIMEOUT_MS = 120000;
const caseTimeout = (c: HarnessCase): number =>
  INVOKE_ALLOWANCE_MS * ((c.given?.executes?.length ?? 0) + Math.max(1, c.delivers?.length ?? 0)) +
  CONVERGENCE_WINDOW_MS + TIMING_MARGIN_MS;

describe("SPEC-RT-002: Harness: clock delivery and observation-mode check", () => {
  let h: Harness;
  beforeAll(async () => {
    h = await createHarness({ configPath: CONFIG_PATH });
  }, HOOK_TIMEOUT_MS);
  afterAll(async () => {
    await h.teardown();
  }, HOOK_TIMEOUT_MS);
  for (const c of CASES) {
    it(c.name, async () => {
      await h.runCase(c, INLINE);
    }, caseTimeout(c));
  }
});
